/private/tmp/agent-runs/default/tmpzfprlhmx/bin/bash -lc "python3 - <<'PY'
p='paper_draft.md'; lines=open(p).read().splitlines()
for i,line in enumerate(lines):
 if line.startswith('where \\\\(\\\\nu\\\\) is the kinematic viscosity.'):
  lines[i]=r'where \\\\(\\\\nu\\\\) is the kinematic viscosity. For each run, density and dynamic viscosity were evaluated for liquid water at the logged temperature and atmospheric pressure using standard temperature-dependent water-property correlations; kinematic viscosity was calculated as \\\\(\\\\nu=\\\\mu/\\\\rho\\\\). Over the logged 13.7–17.6 °C range, \\\\(\\\\nu\\\\) decreases from approximately 1.176×10\\\\u207b\\\\u2076 to 1.064×10\\\\u207b\\\\u2076 m\\\\u00b2 s\\\\u207b\\\\u00b9. The temperature measurement method and instrument accuracy are not recorded.'
 if line.startswith('| 25.4 mm |'):
  lines[i]='| 25.4 mm | 10 | 4.69 × 10\\\\u00b3–2.63 × 10\\\\u2074 | 1.143 (0.033) | 1.093–1.181 |'
 if line.startswith('| 38.1 mm |'):
  lines[i]='| 38.1 mm | 10 | 6.48 × 10\\\\u00b3–3.62 × 10\\\\u2074 | 1.152 (0.026) | 1.103–1.192 |'
 if line.startswith('| 50.8 mm |'):
  lines[i]='| 50.8 mm | 9 | 8.94 × 10\\\\u00b3–4.99 × 10\\\\u2074 | 1.157 (0.034) | 1.107–1.216 |'
 if 'The observed coefficients lie in a relatively narrow band' in line:
  lines[i]='The observed coefficients are similar among the three tested diameters. Because water temperature and test date differ by series, these data do not isolate a diameter effect. No formal fit or statistical comparison is warranted from the present processing alone. The linked figure has not yet been regenerated and still shows the excluded Run 17 point and prior Reynolds-number calculation.'
 if 'The standard deviations in Table 1 describe variation among the ten speed points' in line:
  lines[i]=line.replace('among the ten speed points','among the retained speed points')
 if line.startswith('where \\\\(\\\\nu\\\\)'):
  pass
open(p,'w').write('\\n'.join(lines)+'\\n')
PY
sed -n '41,63p' paper_draft.md"

